<section class="panel"><div class="panel-heading"><div><span class="eyebrow">MANAGE CONTENT</span><h2><?= e($title) ?> <span class="count"><?= $total ?></span></h2></div><a class="btn btn-primary" href="<?= url('admin/'.$type.'/create') ?>">+ Add record</a></div><form class="admin-filters" method="get"><div><label for="q">Search</label><input type="search" name="q" id="q" value="<?= e($q) ?>" placeholder="Search <?= e(strtolower($title)) ?>"></div><?php if($type==='products'): ?><div><label for="category">Category</label><select id="category" name="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $category==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?><button class="btn">Filter</button><a class="btn" href="<?= url('admin/'.$type) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th><?= in_array($type,['products','categories'])?'Name':'Title' ?></th><th><?= $type==='products'?'Category':($type==='contacts'?'Contact information':'Description') ?></th><?php if($type==='products'): ?><th>Documents</th><?php else: ?><th>Order</th><?php endif; ?><th>Status</th><th class="actions-col">Actions</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><div class="table-identity"><?php if(isset($row['image'])): ?><img src="<?= e(media($row['image'])) ?>" alt=""><?php endif; ?><div><strong><?= e($row['name']??$row['title']) ?></strong><small>#<?= $row['id'] ?></small></div></div></td><td><?php if($type==='products'): ?><?= e(array_column($categories,'name','id')[$row['category_id']]??'') ?><?php else: ?><?= e(mb_substr(strip_tags($row['description']??$row['email']),0,90)) ?><?php endif; ?></td><td><?php if($type==='products'): ?><small><?= $row['data_sheet']?'✓ Data sheet':'— Data sheet' ?></small><small><?= $row['safety_sheet']?'✓ Safety sheet':'— Safety sheet' ?></small><?php else: ?><?= $row['sort_order'] ?><?php endif; ?></td><td><?php if($type==='categories'): ?><span class="badge">Category</span><?php else: ?><span class="badge <?= $row['published']?'published':'draft' ?>"><?= $row['published']?'● Published':'○ Draft' ?></span><?php endif; ?></td><td class="actions-col"><div class="row-actions"><a class="btn btn-sm" href="<?= url('admin/'.$type.'/'.$row['id'].'/edit') ?>" aria-label="Edit <?= e($row['name']??$row['title']) ?>">Edit</a><form method="post" class="delete-form" data-name="<?= e($row['name']??$row['title']) ?>" action="<?= url('admin/'.$type.'/'.$row['id'].'/delete') ?>"><?= csrf_field() ?><button class="btn btn-sm danger-text" aria-label="Delete <?= e($row['name']??$row['title']) ?>">Delete</button></form></div></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty">No records found. Add a record or adjust your search.</td></tr><?php endif; ?></tbody></table></div><div class="list-footer"><span><?= $total ?> records · Page <?= $page ?> of <?= $pages ?></span><nav class="pagination" aria-label="Admin pages"><?php if($page>1): ?><a href="<?= e(url('admin/'.$type.'?'.http_build_query(['q'=>$q,'category'=>$category,'page'=>$page-1]))) ?>">← Previous</a><?php endif; ?><?php if($page<$pages): ?><a href="<?= e(url('admin/'.$type.'?'.http_build_query(['q'=>$q,'category'=>$category,'page'=>$page+1]))) ?>">Next →</a><?php endif; ?></nav></div></section>
